def scan_files_simple():
    """Простое сканирование файлов"""
    all_files = []

    if os.path.exists(ARCHIVE_PATH):
        for root, dirs, files in os.walk(ARCHIVE_PATH):
            # Пропускаем скрытые папки
            dirs[:] = [d for d in dirs if not d.startswith('.')]

            for file in files:
                full_path = os.path.join(root, file)
                rel_path = os.path.relpath(full_path, ARCHIVE_PATH)

                all_files.append({
                    'name': file,
                    'path': rel_path,
                    'full_path': full_path,
                    'size': os.path.getsize(full_path) if os.path.exists(full_path) else 0
                })

                # Ограничим для скорости
                if len(all_files) > 1000:
                    return all_files

    return all_files

def read_file_simple(filepath):
    """Простое чтение файла"""
    try:
        full_path = os.path.join(ARCHIVE_PATH, filepath)

        if not os.path.exists(full_path):
            return {'error': 'Файл не найден'}

        # Проверяем размер
        size = os.path.getsize(full_path)
        if size > 1000000:  # >1MB
            return {'error': f'Файл слишком большой ({size} байт)'}

        # Читаем файл
        with open(full_path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read(50000)  # 50KB максимум

            # Пробуем парсить JSON
            if filepath.lower().endswith('.json'):
                try:
                    parsed = json.loads(content)
                    return {
                        'success': True,
                        'type': 'json',
                        'content': parsed,
                        'raw': content,
                        'size': size
                    }
                except:
                    pass

            return {
                'success': True,
                'type': 'text',
                'content': content,
                'size': size,
                'truncated': len(content) >= 50000
            }

    except Exception as e:
        return {'error': str(e)}

# 🔍 ФУНКЦИЯ ПОИСКА ФАЙЛА
def find_file(filename):
    """Ищет файл во всём архиве"""
    results = []

    if os.path.exists(ARCHIVE_PATH):
        for root, dirs, files in os.walk(ARCHIVE_PATH):
            for file in files:
                if filename.lower() in file.lower():
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, ARCHIVE_PATH)
                    results.append({
                        'found_as': file,
                        'relative_path': rel_path,
                        'full_path': full_path,
                        'exists': os.path.exists(full_path)
                    })

    return results

