# 🔍 ПОИСК ПО ВСЕМУ ДИСКУ
@app.route('/search_everywhere/<filename>')
def search_everywhere(filename):
    """Ищет файл на всём диске D:"""
    import glob

    results = []
    search_pattern = f"D:\\**\\*{filename}*"

    try:
        for filepath in glob.glob(search_pattern, recursive=True):
            if os.path.isfile(filepath):
                results.append({
                    'path': filepath,
                    'size': os.path.getsize(filepath) if os.path.exists(filepath) else 0,
                    'in_archive': ARCHIVE_PATH in filepath
                })

                if len(results) > 20:
                    break
    except:
        pass

    return jsonify({
        'search_for': filename,
        'search_pattern': search_pattern,
        'results_found': len(results),
        'results': results
    })

